mapper.select:
SELECT r.*, u.name AS drafter_name, d.dept_nm FROM gw_expense_report r JOIN gw_user u ON u.user_id = r.drafter_id LEFT JOIN gw_dept d ON d.dept_id = r.dept_id WHERE 1=1
AND r.status_cd = #{status}
AND r.dept_id = #{deptId}
ORDER BY r.created_at DESC LIMIT 500

mapper.update:
UPDATE gw_dept_budget
   SET used_amount = used_amount + #{amount}
 WHERE dept_id = #{deptId} AND account_cd = #{accountCd}
   AND year = #{year} AND month = #{month}
